INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(24501, 'Luke 16:8', 'Luke', 16, 8, '&nbsp;او مالِک د خپل بې‌ايمانه ناظر د دې هوښيارتيا ستائينه وکړه، ځکه چې د دې پيړۍ خلق په خپلو کښې په لېن دېن کولو کښې د ايماندارانو نه زيات هوښيار دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24502, 'Luke 16:9', 'Luke', 16, 9, '&nbsp;نو ځکه زۀ تاسو ته وايم چې د دُنيا په مال دولت خپل ځان له دوستان جوړ کړئ نو چې کله مال دولت درنه لاړ شى نو دا خلق به تاسو په ابدى کور کښې قبول کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24503, 'Luke 16:10', 'Luke', 16, 10, '&nbsp;کوم سړے چې په لږ کار کښې ديانتداره وى، هغه به په غټ کار کښې هم ديانتداره وى او کوم سړے چې په لږ کښې بدديانته وى، هغه به په ډېرو کښې هم بدديانته وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24504, 'Luke 16:11', 'Luke', 16, 11, '&nbsp;نو کۀ چرې تاسو ځان د دې دُنيا په دولت کښې ديانتداره ثابت نۀ کړو نو په حقيقى دولت کښې به په تاسو باندې څوک اِعتبار وکړى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24505, 'Luke 16:12', 'Luke', 16, 12, '&nbsp;او کۀ چرې تاسو په پردى مال دولت کښې ځان بدديانته ثابت کړے وى نو بيا به داسې څوک وى چې تاسو له به خپل مال دولت درکړى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24506, 'Luke 16:13', 'Luke', 16, 13, '&nbsp;يو غلام هم د دوو مالِکانو خِدمت نۀ شى کولے، ځکه چې يا خو به هغه د يو نه نفرت کوى او د بل سره مينه، او يا به هغه د يو وفادار وى او د بل نه به کرکه کوى. تاسو د خُدائ پاک او د مال دولت دواړو يو ځائ خِدمت نۀ شئ کولے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24507, 'Luke 16:14', 'Luke', 16, 14, '&nbsp;او فريسيان څوک چې په مال مئين وُو هغوئ چې دا خبرې واورېدلې نو په عيسىٰ پورې يې خندا وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24508, 'Luke 16:15', 'Luke', 16, 15, '&nbsp;عيسىٰ ورته وفرمائيل، ”هم تاسو خلق خپل اولس په دې دوکه کوئ چې ګنې تاسو صادقان يئ خو خُدائ پاک ستاسو زړونه پېژنى. ځکه چې کوم څيزونه چې د خلقو په نظر کښې د صِفت وى، هغه د خُدائ پاک په نظر کښې پليت وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24509, 'Luke 16:16', 'Luke', 16, 16, '&nbsp;د يحيىٰ تر وخته د شريعت او نبيانو سلسله جارى وه. د دې نه پس د خُدائ پاک د بادشاهۍ د زيرى بيان اورولے شو نو د هر چا زړۀ وو چې په هغې کښې داخل شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24510, 'Luke 16:17', 'Luke', 16, 17, '&nbsp;د زمکې او آسمان ختمېدل د شريعت نه د يو حرف يا زبر قدرې ورانولو په نسبت آسان کار دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24511, 'Luke 16:18', 'Luke', 16, 18, '&nbsp;کوم سړے چې خپله ښځه طلاقه کړى او د بلې سره وادۀ وکړى نو هغه زنا کوى او هغه سړے څوک چې د طلاقې شوې ښځې سره وادۀ وکړى نو هغه هم زنا کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24512, 'Luke 16:19', 'Luke', 16, 19, '&nbsp;يو مالداره سړے وو چې کاسنى او د نرم کتان جامې يې اچولې او هره ورځ به يې ډېر په شان شوکت خلقو له دعوتونه ورکول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24513, 'Luke 16:20', 'Luke', 16, 20, '&nbsp;او يو عاجز سړے چې نوم يې لعزر وو او په وجود يې ډيرې دانې راختلې وې، د هغۀ په دروازه کښې پروت وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24514, 'Luke 16:21', 'Luke', 16, 21, '&nbsp;او هغه به د هغه ټوکړو خوړلو په طمع وو کومې به چې د دې مالداره سړى دسترخوان نه پاتې شوې وې، بلکې سپى به هم راتلل او د هغۀ زخمونه به يې څټل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24515, 'Luke 16:22', 'Luke', 16, 22, '&nbsp;آخر يوه ورځ هغه عاجز سړے مړ شو او فرښتو يوړو او د اِبراهيم په غېږ کښې يې واچولو. هغه مالداره سړے هم مړ شو او ښخ کړے شو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24516, 'Luke 16:23', 'Luke', 16, 23, '&nbsp;او په عالمِ ارواح کښې چرته چې هغه په عذاب وو، هغۀ چې پورته وکتل نو لرې يې لعزر د اِبراهيم په غېږ کښې وليدلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24517, 'Luke 16:24', 'Luke', 16, 24, '&nbsp;هغۀ چغې کړې، اے پلاره، اِبراهيمه. په ما رحم وکړه. دا لعزر راولېږه چې خپل د ګوتې سر په اوبو کښې لوند کړى چې زما ژبه پرې يخه کړى ځکه چې زۀ په دې اور کښې ډېر په عذاب يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24518, 'Luke 16:25', 'Luke', 16, 25, '&nbsp;خو اِبراهيم ورته وفرمائيل چې، هغه وخت ياد کړه زويه. په دُنيا کښې ټول نعمتونه ستا په نصيب وُو او ټولې بدبختۍ د لعزر په نصيب وې. اوس هغه دلته په آرام دے او تۀ په عذاب کښې يې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24519, 'Luke 16:26', 'Luke', 16, 26, '&nbsp;خو بله خبره دا ده چې زمونږ او ستا تر مينځه يوه لويه کنده ده چې د هغې نه نۀ څوک پورې وتلے شى او نۀ ترېنه څوک دېخوا راتلے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24520, 'Luke 16:27', 'Luke', 16, 27, '&nbsp;مالداره سړى جواب ورکړو چې بيا نو پلاره، زۀ درته زارى مِنت کوم چې تۀ دے زمونږ کور ته ولېږه', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24521, 'Luke 16:28', 'Luke', 16, 28, '&nbsp;چرته چې زما پينځۀ وروڼه دى چې هغوئ خبرداره کړى، هسې نه چې هغوئ هم په دې عذاب کښې ګېر شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24522, 'Luke 16:29', 'Luke', 16, 29, '&nbsp;خو اِبراهيم ورته وفرمائيل چې د هغوئ سره موسىٰ او نور نبيان شته، په کار دى چې دوئ هغوئ ته غوږ ونيسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24523, 'Luke 16:30', 'Luke', 16, 30, '&nbsp;خو هغۀ جواب ورکړو چې، نه، پلاره اِبراهيمه. کۀ د مړو نه څوک هغوئ ته لاړ شى نو هغوئ به هله توبه ګار شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24524, 'Luke 16:31', 'Luke', 16, 31, '&nbsp;اِبراهيم جواب ورکړو، کۀ چرې هغوئ د موسىٰ او د نورو نبيانو خبرو ته غوږ نۀ ږدى نو کۀ څوک د قبر نه ورپاڅى هم نو هغوئ به پرې باور ونۀ کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24525, 'Luke 17:1', 'Luke', 17, 1, '&nbsp;عيسىٰ خپلو مريدانو ته وفرمائيل، ”تيندکونه به خامخا راځى خو چې د چا د لاسه دا راځى، د هغوئ په حال افسوس دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24526, 'Luke 17:2', 'Luke', 17, 2, '&nbsp;د هغۀ دپاره به دا ښۀ وى چې د هغۀ په غاړه کښې د ژرندې پل واچولے شى او په درياب کښې وغورزولے شى، په ځائ د دې چې په دې وړو کښې يو له هم تيندک ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24527, 'Luke 17:3', 'Luke', 17, 3, '&nbsp;خبردار اوسئ. کۀ چرې ستاسو ورور څۀ ګناه وکړى نو وې رټئ او کۀ هغه پښېمانه شى نو وې بخښئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24528, 'Luke 17:4', 'Luke', 17, 4, '&nbsp;او کۀ چرې هم هغه په ورځ کښې اووۀ ځله ستا خلاف ګناه وکړى او بيا اووۀ ځله درله راشى او داسې ووائى چې زۀ توبه کوم نو تۀ يې معاف کړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24529, 'Luke 17:5', 'Luke', 17, 5, '&nbsp;مريدانو مالِک ته ووئيل چې، ”زمونږ ايمان قوى کړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24530, 'Luke 17:6', 'Luke', 17, 6, '&nbsp;نو مالِک ورته جواب ورکړو، ”کۀ چرې ستاسو ايمان د شړشمو د دانې هومره هم وى نو کۀ تاسو د تُوت دې ونې ته ووايئ چې د بېخه ووځه او په سمندر کښې لاهو شه، نو دا به ستاسو حُکم ومنى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24531, 'Luke 17:7', 'Luke', 17, 7, '&nbsp;کۀ چرې د يو کس نوکر د يوې او ګډو څرولو نه راواپس شى، نو ولې د هغۀ نېک به ورته دا وائى چې زر راشه او ما سره روټۍ ته کښېنه؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24532, 'Luke 17:8', 'Luke', 17, 8, '&nbsp;نه، هغه به ورته دا وائى چې زما روټۍ تياره کړه، ملا تړلے ودرېږه او زما خِدمت کوه. او تۀ به زما نه وروستو روټۍ وخورې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24533, 'Luke 17:9', 'Luke', 17, 9, '&nbsp;ولې هغه به د هغه نوکر شُکر ګزارى ونۀ کړى چې د دۀ حکم يې منلے وو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24534, 'Luke 17:10', 'Luke', 17, 10, '&nbsp;دغه شان کله چې تاسو هغه هر څۀ چې تاسو ته يې حکم شوے دے پوره کړئ نو بيا تاسو ته داسې وئيل په کار دى چې مونږ د تعريف قابل نوکران نۀ يُو خو مونږ صرف خپل فرض پوره کړو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24535, 'Luke 17:11', 'Luke', 17, 11, '&nbsp;کله چې عيسىٰ يروشلم ته روان وو نو هغه د سامريه او د ګليل تر مينځه تېرېدلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24536, 'Luke 17:12', 'Luke', 17, 12, '&nbsp;کله چې هغه يو کلى ته ورسېدو نو لس جذاميان يې هلته وليدل. هغوئ په څۀ فاصله کښې ولاړ وُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24537, 'Luke 17:13', 'Luke', 17, 13, '&nbsp;او عيسىٰ ته يې نعرې کړې، ”اے مالِکه، په مونږ رحم وکړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24538, 'Luke 17:14', 'Luke', 17, 14, '&nbsp;هر کله چې هغۀ هغوئ وليدل نو ورته يې وفرمائيل، ”لاړ شئ او خپل ځانونه اِمامانو ته وښايئ.“ او کله چې هغوئ لا په لاره روان وُو نو هغوئ پاک کړے شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24539, 'Luke 17:15', 'Luke', 17, 15, '&nbsp;نو په هغوئ کښې چې يو تن خپل ځان روغ وليدلو نو واپس شو او په چغو چغو يې د خُدائ پاک ثناء ووئيله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24540, 'Luke 17:16', 'Luke', 17, 16, '&nbsp;هغه د عيسىٰ په پښو کښې پرېوتو او د هغۀ شکريه يې ادا کړه. او هغه يو سامرى وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24541, 'Luke 17:17', 'Luke', 17, 17, '&nbsp;بيا عيسىٰ وفرمائيل چې، ”ولې لس واړه پاک نۀ کړے شوئ؟ نو هغه نور نهۀ څۀ شول؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24542, 'Luke 17:18', 'Luke', 17, 18, '&nbsp;بې له دې يو مسافر نه بل يو هم داسې نۀ وو چې واپس راغلے وے او د خُدائ پاک ثناء يې وئيلے وے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24543, 'Luke 17:19', 'Luke', 17, 19, '&nbsp;او عيسىٰ هغه سړى ته وفرمائيل، ”پاڅه او لاړ شه، خپل ايمان تۀ جوړ کړې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24544, 'Luke 17:20', 'Luke', 17, 20, '&nbsp;فريسيانو د عيسىٰ نه تپوس وکړو چې، ”د خُدائ پاک بادشاهى به کله راځى؟“ هغۀ وفرمائيل چې، ”تاسو د نښو په ليدلو دا نۀ شئ وئيلے چې د خُدائ پاک بادشاهى به کله راځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24545, 'Luke 17:21', 'Luke', 17, 21, '&nbsp;نۀ څوک داسې وئيلے شى چې ګورئ هغه دلته ده. يا هلته ده. ځکه چې په حقيقت کښې د خُدائ پاک بادشاهى ستاسو په مينځ کښې ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24546, 'Luke 17:22', 'Luke', 17, 22, '&nbsp;بيا عيسىٰ مريدانو ته وفرمائيل چې، ”داسې وخت به راشى چې تاسو به د اِبن آدم د راتلو په طمع يئ خو تاسو به يې ليدلے نۀ شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24547, 'Luke 17:23', 'Luke', 17, 23, '&nbsp;خلق به تاسو ته وائى چې ګورئ هغه هلته دے يا دلته دے، خو هلته مۀ ځئ او مۀ هغوئ پسې منډې وهئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24548, 'Luke 17:24', 'Luke', 17, 24, '&nbsp;لکه څنګه چې برېښنا د آسمان د يو سر نه تر بله سره پورې رسى، دغه شان به د اِبن آدم راتلل وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24549, 'Luke 17:25', 'Luke', 17, 25, '&nbsp;خو اول به هغه خامخا ډېر مصيبت وزغمى او دا پيړۍ به يې رد کړى', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24550, 'Luke 17:26', 'Luke', 17, 26, '&nbsp;لکه څنګه چې د نوح په زمانه کښې شوى وُو، هم هغه شان به د اِبن آدم د راتلو په ورځو کښې وشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24551, 'Luke 17:27', 'Luke', 17, 27, '&nbsp;هغوئ تر هغې ورځې پورې خوړل څښل او ودونه يې کول ترڅو چې نوح خپلې کشتۍ ته ننوتو او سېلاب راغلو او هغوئ ټول يې غرق کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
