(24553, 'Luke 17:29', 'Luke', 17, 29, '&nbsp;خو په کومه ورځ چې لوط د سدوم نه ووتلو نو د آسمان نه اور او ګوګړ ورېدل شروع شول او دوئ يې ټول تباه کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24554, 'Luke 17:30', 'Luke', 17, 30, '&nbsp;دغه شان به د اِبن آدم د راتلو په ورځ هم وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24555, 'Luke 17:31', 'Luke', 17, 31, '&nbsp;په هغه ورځ هر څوک چې د چت دپاسه وى او سامان يې ښکته وى نو هغه دې د سامان اوچتولو دپاره هيڅکله هم ښکته نۀ راکوزيږى او هم دغه شان څوک چې په پټى کښې وى هغه دې کور ته نۀ واپس کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24556, 'Luke 17:32', 'Luke', 17, 32, '&nbsp;د لوط ښځه راياده کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24557, 'Luke 17:33', 'Luke', 17, 33, '&nbsp;څوک چې خپل ځان ساتل غواړى هغه به يې بائيلى، خو څوک چې ځان بائيلى، هغه به يې وساتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24558, 'Luke 17:34', 'Luke', 17, 34, '&nbsp;زۀ تاسو ته وايم چې په هغه شپه به په يو کټ کښې دوه کسان وى، يو به واخستلے شى او بل به پرېښودلے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
