(24560, 'Luke 17:36', 'Luke', 17, 36, '&nbsp;دوه سړى به په پټى کښې وى، يو به واخستلے شى او بل به پرېښودلے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24561, 'Luke 17:37', 'Luke', 17, 37, '&nbsp;هغوئ چې دا واورېدل نو تپوس يې وکړو، ”دا به چرته وى مالِکه؟“ عيسىٰ ورته وفرمائيل، ”چرته چې مرداره وى هلته به ټپوسان راټوليږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24562, 'Luke 18:1', 'Luke', 18, 1, '&nbsp;بيا عيسىٰ مريدانو ته يو مِثال ووئيلو، او ورته يې دا وښودل چې هغوئ دې ضرور بار بار دُعا غواړى او زړۀ دې نۀ بائيلى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24563, 'Luke 18:2', 'Luke', 18, 2, '&nbsp;نو هغۀ وفرمائيل چې، ”په يو ښار کښې يو قاضى وو چې نۀ ورسره د خُدائ پاک يره وه او نۀ يې د خلقو پرواه کوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24564, 'Luke 18:3', 'Luke', 18, 3, '&nbsp;او هم په دغه ښار کښې يوه کونډه وه چې هغه به بيا بيا هغۀ له راتله او ورته به يې وئيل چې زما د مخالفينو او زما تر مينځه اِنصاف وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24565, 'Luke 18:4', 'Luke', 18, 4, '&nbsp;ډېره موده هغۀ اِنکار کولو خو آخر يې په زړۀ کښې ووئيل، حقه خو دا ده چې زۀ نۀ خو د خُدائ پاک نه يرېږم او نۀ د خلقو پرواه کوم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24566, 'Luke 18:5', 'Luke', 18, 5, '&nbsp;خو اوس دا کونډه زما دپاره داسې بلا جوړه شوې ده او زۀ به د دې حق دې له ورکړم، هسې نۀ چې په بار بار راتلو ما تر پوزې راولى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24567, 'Luke 18:6', 'Luke', 18, 6, '&nbsp;بيا مالِک عيسىٰ وفرمائيل، ”تاسو دې بې‌اِنصافه قاضى ته غوږ شئ چې دۀ څۀ ووئيل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24568, 'Luke 18:7', 'Luke', 18, 7, '&nbsp;نو ولې خُدائ پاک به د خپلو غوره شوو دُعا نۀ اورى څوک چې ورته شپه او ورځ زارى او مِنت کوى؟ ولې هغه به د دوئ په مدد کولو کښې ډېر وخت ولګوى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24569, 'Luke 18:8', 'Luke', 18, 8, '&nbsp;زۀ تاسو ته وايم، هغه به ډېر زر د هغوئ سره اِنصاف وکړى. خو کله چې اِبن آدم دوباره راشى، نو ولې هغه به څوک ايماندار په زمکه پېدا کړى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24570, 'Luke 18:9', 'Luke', 18, 9, '&nbsp;عيسىٰ هغه خلقو ته هم چې په خپل ځان يې باور کولو چې مونږ صادقان يُو او نور يې سپک ګڼل، دا مِثال ووئيلو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24571, 'Luke 18:10', 'Luke', 18, 10, '&nbsp;”دوه سړى د دُعا دپاره د خُدائ کور ته لاړل، يو فريسى وو او بل محصولچى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24572, 'Luke 18:11', 'Luke', 18, 11, '&nbsp;فريسى ودرېدو او داسې دُعا يې شروع کړه، اے خُدايه پاکه، ستا شُکر دے چې زۀ د نورو خلقو په شان نۀ خو دوکه مار، نۀ بې‌ايمانه، نۀ زناکار او نۀ لکه د هغه محصولچى په شان يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24573, 'Luke 18:12', 'Luke', 18, 12, '&nbsp;زۀ په هفته کښې دوه روژې نيسم او څۀ چې ګټم خُدائ پاک ته د هغې نه لسمه ورکوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24574, 'Luke 18:13', 'Luke', 18, 13, '&nbsp;خو محصولچى لرې ولاړ وو او پاس آسمان ته يې نۀ کتل او خپله سينه يې وهله او وئيل يې، اے خُدايه پاکه، په ما رحم وکړه، زۀ ستا ګناه ګار يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24575, 'Luke 18:14', 'Luke', 18, 14, '&nbsp;زۀ تاسو ته وايم چې هم دا سړے د هغه اولنى سړى نه زيات صادق کور ته واپس لاړو، ځکه هر څوک چې ځان اوچتوى، هغه به عاجز کړے شى او څوک چې ځان عاجز کړى، هغه به اوچت کړے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24576, 'Luke 18:15', 'Luke', 18, 15, '&nbsp;خلقو عيسىٰ له خپل ماشومان راوستل چې د برکت دپاره لاس پرې کېږدى. کله چې مريدانو دوئ وليدل نو وې رټل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24577, 'Luke 18:16', 'Luke', 18, 16, '&nbsp;خو عيسىٰ هغه ماشومان راوبلل او وې فرمائيل، ”ماشومان ما ته راپرېږدئ، دوئ مۀ منع کوئ ځکه چې د خُدائ پاک بادشاهى هم د داسې خلقو ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24578, 'Luke 18:17', 'Luke', 18, 17, '&nbsp;زۀ تاسو ته رښتيا وايم، هر څوک چې د خُدائ پاک بادشاهى لکه د ماشوم قبوله نۀ کړى، هغوئ به هيڅکله په دې کښې داخل نۀ شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24579, 'Luke 18:18', 'Luke', 18, 18, '&nbsp;يو حاکِم د عيسىٰ نه دا تپوس وکړو، ”اے نېکه اُستاذه. داسې څۀ وکړم چې د تل ژوندون وارث شم؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24580, 'Luke 18:19', 'Luke', 18, 19, '&nbsp;عيسىٰ هغۀ ته وفرمائيل، ”تۀ ما ته نېک ولې وائې؟ د خُدائ پاک نه بغېر بل هيڅوک نېک نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24581, 'Luke 18:20', 'Luke', 18, 20, '&nbsp;تا ته د شريعت حُکمونه خو معلوم دى، زنا مۀ کوه، قتل مۀ کوه، غلا مۀ کوه، د دروغو ګواهى مۀ کوه او د خپل مور پلار عزت کوه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
