(24593, 'Luke 18:32', 'Luke', 18, 32, '&nbsp;هغه به غېر‌يهوديانو ته حواله کړے شى، هغوئ به په هغۀ پورې ټوقې وکړى او بد سلوکى به ورسره وکړى او توکاڼې به پرې وتوکى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
