(24599, 'Luke 18:38', 'Luke', 18, 38, '&nbsp;نو هغۀ چغې کړې، ”اے عيسىٰ د داؤد زويه، په ما رحم وکړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24600, 'Luke 18:39', 'Luke', 18, 39, '&nbsp;مخکښې چې کوم خلق روان وُو، هغوئ ورته په سخته ووئيل چې، ”چپ شه.“ خو هغۀ چغې لا نورې هم زياتې کړې چې، ”اے د داؤد زويه. په ما رحم وکړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');